import {
  Component,
  Element,
  Event,
  EventEmitter,
  Prop,
  h,
} from "@stencil/core";
import { VNode } from "@stencil/core/internal";
import { keyBy } from "../../utils/function-helper";

import { HbrTableNS, Observable, Selection } from "../../table-sub/interfaces";
import ColumnGroupsRenderer from "../../table-sub//plugins/groupingColumn/columnGroupsRenderer";
import { Groups } from "../../table-sub/store/dataSource/data.store";
import {
  HEADER_ACTUAL_ROW_CLASS,
  HEADER_ROW_CLASS,
} from "../../table-sub//utils/consts";
import { getElement } from "../table-data/columnService";
import HeaderRenderer from "./headerRenderer";

@Component({
  tag: "hbr-table-header",
  styleUrl: "style.scss",
})
export class HbrgrHeaderComponent {
  private columnDidRender = [];
  @Element() element!: HTMLHbrTableHeaderElement;
  @Prop() viewportCol: Observable<HbrTableNS.ViewportState>;
  @Prop() dimensionCol: Observable<HbrTableNS.DimensionSettingsState>;
  @Prop() selectionStore: Observable<Selection.SelectionStoreState>;

  @Prop() parent = "";
  @Prop() groups: Groups;
  @Prop() groupingDepth = 0;
  @Prop() canResize: boolean;
  @Prop() colData: HbrTableNS.ColumnRegular[];
  @Prop() columnFilter: boolean;
  @Prop() tbSelf: any;
  @Prop({ reflect: true }) role;

  @Event() initialHeaderClick: EventEmitter<HbrTableNS.InitialHeaderClick>;
  @Event() headerresize: EventEmitter<HbrTableNS.ViewSettingSizeProp>;
  @Event() headerdblClick: EventEmitter<HbrTableNS.InitialHeaderClick>;

  private onResize({ width }: { width?: number }, index: number): void {
    this.headerresize.emit({ [index]: width || 0 });
  }

  private onResizeGroup(
    changedX: number,
    startIndex: number,
    endIndex: number
  ): void {
    const sizes: HbrTableNS.ViewSettingSizeProp = {};
    const cols = keyBy(this.viewportCol.get("items"), "itemIndex");
    const change = changedX / (endIndex - startIndex + 1);
    for (let i = startIndex; i <= endIndex; i++) {
      const item = cols[i];
      if (item) {
        sizes[i] = item.size + change;
      }
    }
    this.headerresize.emit(sizes);
  }

  componentDidRender() {
    this.columnDidRender.forEach(([didRender, data, colTemplate]) => {
      const ele = getElement(colTemplate);
      return didRender(data, ele, this.tbSelf.source, colTemplate);
    });
  }

  render() {
    this.columnDidRender = [];
    const cols = this.viewportCol.get("items");
    const range = this.selectionStore?.get("range");
    const cells: VNode[] = [];
    const visibleProps: { [prop: string]: number } = {};

    // render header columns
    for (const rgCol of cols) {
      const colData = this.colData[rgCol.itemIndex];
      cells.push(
        <HeaderRenderer
          table={this.tbSelf}
          columnDidRender={this.columnDidRender}
          range={range}
          column={rgCol}
          data={colData}
          canFilter={!!this.columnFilter}
          canResize={this.canResize}
          onResize={(e) => this.onResize(e, rgCol.itemIndex)}
          onDoubleClick={(e) => this.headerdblClick.emit(e)}
          onClick={(e) => this.initialHeaderClick.emit(e)}
        />
      );
      visibleProps[colData?.prop] = rgCol.itemIndex;
    }

    return [
      <div class="group-rgRow">
        <ColumnGroupsRenderer
          table={this.tbSelf}
          canResize={this.canResize}
          visibleProps={visibleProps}
          groups={this.groups}
          dimensionCol={this.dimensionCol.state}
          depth={this.groupingDepth}
          onResize={(changedX, startIndex, endIndex) =>
            this.onResizeGroup(changedX, startIndex, endIndex)
          }
        />
      </div>,
      <div class={`${HEADER_ROW_CLASS} ${HEADER_ACTUAL_ROW_CLASS}`} role="row">
        {cells}
      </div>,
    ];
  }
}
