import {
  Component,
  Element,
  Event,
  EventEmitter,
  Host,
  Method,
  Prop,
  Watch,
  h,
} from "@stencil/core";
import { each } from "../../utils/function-helper";

import { HbrTableNS } from "../../table-sub/interfaces";
import LocalScrollService from "../../table-sub/services/localScrollService";
import {
  CONTENT_SLOT,
  FOOTER_SLOT,
  HEADER_SLOT,
} from "../table/viewport.helpers";
import GridResizeService from "../table/viewport.resize.service";

/**
 * Service for tracking grid scrolling
 */
@Component({
  tag: "hbr-viewport-scroll",
  styleUrl: "viewport-scroll.scss",
})
export class HbrgrViewportScroll {
  @Event({ bubbles: false })
  scrollViewport: EventEmitter<HbrTableNS.ViewPortScrollEvent>;
  @Event() resizeViewport: EventEmitter<HbrTableNS.ViewPortResizeEvent>;
  @Event() scrollchange: EventEmitter<{
    type: HbrTableNS.DimensionType;
    hasScroll: boolean;
  }>;
  private scrollThrottling = 30;

  /**
   * Width of inner content
   */
  @Prop() contentWidth = 0;
  /**
   * Height of inner content
   */
  @Prop() contentHeight = 0;

  @Prop() tbSelf;

  private oldValY = this.contentHeight;
  private oldValX = this.contentWidth;

  @Element() horizontalScroll: HTMLHbrViewportScrollElement;
  private verticalScroll: HTMLElement;
  private header: HTMLElement;
  private footer: HTMLElement;

  /**
   * Static functions to bind wheel change
   */
  private horizontalMouseWheel: (e: WheelEvent) => void;
  private verticalMouseWheel: (e: WheelEvent) => void;

  private horisontalResize: GridResizeService;
  private scrollService: LocalScrollService;

  /**
   * emitted when table height changes with change of query
   */
  @Event({ eventName: "hbr-content-height-change" })
  hbrContentHeightChange: EventEmitter;

  @Watch("contentHeight")
  handleContentHeightChanged(...params) {
    this.hbrContentHeightChange.emit({
      height: params[0],
      oldHeight: params[1],
    });
  }

  /**
   * Last mw event time for trigger scroll function below
   * If mousewheel function was ignored we still need to trigger render
   */
  private mouseWheelScroll: Record<HbrTableNS.DimensionType, number> = {
    rgCol: 0,
    rgRow: 0,
  };
  @Method() async setScroll(e: HbrTableNS.ViewPortScrollEvent): Promise<void> {
    this.latestScrollUpdate(e.dimension);
    this.scrollService?.setScroll(e);
  }

  /**
   * update on delta in case we don't know existing position or external change
   * @param e
   */
  @Method() async changeScroll(
    e: HbrTableNS.ViewPortScrollEvent
  ): Promise<HbrTableNS.ViewPortScrollEvent> {
    if (e.delta) {
      switch (e.dimension) {
        case "rgCol":
          e.coordinate = this.horizontalScroll.scrollLeft + e.delta;
          break;
        case "rgRow":
          e.coordinate = this.verticalScroll.scrollTop + e.delta;
          break;
      }
      this.setScroll(e);
    }
    return e;
  }

  connectedCallback() {
    /**
     * Bind scroll functions for farther usage
     */

    if ("ontouchstart" in document.documentElement) {
      this.scrollThrottling = 0;
    } else {
      this.verticalMouseWheel = this.onVerticalMouseWheel.bind(
        this,
        "rgRow",
        "deltaY"
      );
      this.horizontalMouseWheel = this.onHorizontalMouseWheel.bind(
        this,
        "rgCol",
        "deltaX"
      );
    }
    /**
     * Create local scroll service
     */
    this.scrollService = new LocalScrollService({
      beforeScroll: (e) => this.scrollViewport.emit(e),
      afterScroll: (e) => {
        switch (e.dimension) {
          case "rgCol":
            this.horizontalScroll.scrollLeft = e.coordinate;
            break;
          case "rgRow":
            this.verticalScroll.scrollTop = e.coordinate;
            break;
        }
      },
    });
  }

  componentDidLoad() {
    /**
     * Track horizontal viewport resize
     */
    this.horisontalResize = new GridResizeService(this.horizontalScroll, {
      resize: (entries) => {
        let height = entries[0]?.contentRect.height || 0;
        if (height) {
          height -= this.header.clientHeight + this.footer.clientHeight;
        }
        const els = {
          rgRow: {
            size: height,
            contentSize: this.contentHeight,
            scroll: this.verticalScroll.scrollTop,
          },
          rgCol: {
            size: entries[0]?.contentRect.width || 0,
            contentSize: this.contentWidth,
            scroll: this.horizontalScroll.scrollLeft,
          },
        };
        each(els, (item, dimension: HbrTableNS.DimensionType) => {
          this.resizeViewport.emit({ dimension, size: item.size });
          this.scrollService?.scroll(item.scroll, dimension, true);
          // track scroll visibility on outer element change
          this.setScrollVisibility(dimension, item.size, item.contentSize);
        });
      },
    });
    /** Emit initial height of content */
    this.handleContentHeightChanged(this.contentHeight, 0);
  }

  /**
   * Check if scroll present or not per type
   * Trigger this method on inner content size change or on outer element size change
   * If inner content bigger then outer size then scroll is present and mousewheel binding required
   * @param type - dimension type 'rgRow/y' or 'rgCol/x'
   * @param size - outer content size
   * @param innerContentSize - inner content size
   */
  setScrollVisibility(
    type: HbrTableNS.DimensionType,
    size: number,
    innerContentSize: number
  ) {
    // test if scroll present
    const hasScroll = size < innerContentSize;
    let el: HTMLElement;
    // event reference for binding
    let event: (e: MouseEvent) => void;
    switch (type) {
      case "rgCol":
        el = this.horizontalScroll;
        event = this.horizontalMouseWheel;
        break;
      case "rgRow":
        el = this.verticalScroll;
        event = this.verticalMouseWheel;
        break;
    }
    // based on scroll visibility assign or remove class and event
    if (hasScroll) {
      el.classList.add(`scroll-${type}`);
      el.addEventListener("mousewheel", event);
    } else {
      el.classList.remove(`scroll-${type}`);
      el.removeEventListener("mousewheel", event);
    }
    this.scrollchange.emit({ type, hasScroll });
  }

  disconnectedCallback() {
    this.verticalScroll.removeEventListener(
      "mousewheel",
      this.verticalMouseWheel
    );
    this.horizontalScroll.removeEventListener(
      "mousewheel",
      this.horizontalMouseWheel
    );
    this.horisontalResize.destroy();
  }

  async componentDidRender() {
    // scroll update if number of rows changed
    if (this.contentHeight < this.oldValY && this.verticalScroll) {
      if (this.tbSelf.syncScrollOnUpdate) {
        this.verticalScroll.scrollTop += this.contentHeight - this.oldValY;
      }
    }
    this.oldValY = this.contentHeight;

    // scroll update if number of cols changed
    if (this.contentWidth < this.oldValX) {
      this.horizontalScroll.scrollLeft += this.contentWidth - this.oldValX;
    }
    this.oldValX = this.contentWidth;

    this.scrollService.setParams(
      {
        contentSize: this.contentHeight,
        clientSize: this.verticalScroll.clientHeight,
        virtualSize: 0,
      },
      "rgRow"
    );

    this.scrollService.setParams(
      {
        contentSize: this.contentWidth,
        clientSize: this.horizontalScroll.clientWidth,
        virtualSize: 0,
      },
      "rgCol"
    );
    this.setScrollVisibility(
      "rgRow",
      this.verticalScroll.clientHeight,
      this.contentHeight
    );
    this.setScrollVisibility(
      "rgCol",
      this.horizontalScroll.clientWidth,
      this.contentWidth
    );
  }

  render() {
    return (
      <Host onScroll={(e: MouseEvent) => this.onScroll("rgCol", e)}>
        <div
          class="inner-content-table"
          style={{ width: `${this.contentWidth}px` }}
        >
          <div
            class="header-wrapper"
            ref={(e) => {
              this.header = e;
            }}
          >
            <slot name={HEADER_SLOT} />
          </div>
          <div
            class="vertical-inner"
            ref={(el) => {
              this.verticalScroll = el;
            }}
            onScroll={(e: MouseEvent) => this.onScroll("rgRow", e)}
          >
            <div
              class="content-wrapper"
              style={{ height: `${this.contentHeight}px` }}
            >
              <slot name={CONTENT_SLOT} />
            </div>
          </div>
          <div
            class="footer-wrapper"
            ref={(e) => {
              this.footer = e;
            }}
          >
            <slot name={FOOTER_SLOT} />
          </div>
        </div>
      </Host>
    );
  }

  /**
   * Extra layer for scroll event monitoring, where MouseWheel event is not passing
   * We need to trigger scroll event in case there is no mousewheel event
   */
  private onScroll(dimension: HbrTableNS.DimensionType, e: MouseEvent) {
    const target = e.target as HTMLElement | undefined;
    let scroll = 0;
    switch (dimension) {
      case "rgCol":
        scroll = target?.scrollLeft;
        break;
      case "rgRow":
        scroll = target?.scrollTop;
        break;
    }
    const change = new Date().getTime() - this.mouseWheelScroll[dimension];
    if (change > this.scrollThrottling) {
      this.scrollService?.scroll(
        scroll,
        dimension,
        undefined,
        undefined,
        this.getScrollDetail()
      );
    }
  }

  getScrollDetail(): HbrTableNS.ViewPortScrollEventScroll {
    const rect = this.verticalScroll?.getBoundingClientRect();
    if (rect) {
      return {
        height: this.contentHeight - rect.height,
        scrollTop: this.verticalScroll.scrollTop,
      };
    } else {
      // @ts-ignore
      return {};
    }
  }

  /** remember last mw event time */
  private latestScrollUpdate(dimension: HbrTableNS.DimensionType) {
    this.mouseWheelScroll[dimension] = new Date().getTime();
  }

  reachTop = () => this.verticalScroll.scrollTop <= 0;
  reachBottom = () => {
    const rect = this.verticalScroll?.getBoundingClientRect();
    if (rect) {
      return (
        this.verticalScroll.scrollTop >=
        Math.ceil(this.contentHeight) - Math.ceil(rect.height)
      );
    }
  };
  /**
   * On vertical mousewheel event
   * @param type
   * @param delta
   * @param e
   */
  private onVerticalMouseWheel(
    type: HbrTableNS.DimensionType,
    delta: "deltaX" | "deltaY",
    e: WheelEvent
  ) {
    // stop the native event when the scrolling is not reach the top/bottom
    if (delta === "deltaY") {
      if (!this.reachTop() && !this.reachBottom()) {
        e.preventDefault(); // hijacks scroll from page
      }
    }

    if (this.tbSelf?.paginationPlugin?.paginationRef) {
      this.handlePaginationScroll(type, delta, e);
    } else {
      const pos = this.verticalScroll.scrollTop + e[delta];
      this.scrollService?.scroll(
        pos,
        type,
        undefined,
        e[delta],
        this.getScrollDetail()
      );
      this.latestScrollUpdate(type);
    }
  }

  handlePaginationScroll(
    type: HbrTableNS.DimensionType,
    delta: "deltaX" | "deltaY",
    e: WheelEvent
  ) {
    let pos = this.verticalScroll.scrollTop + e[delta];
    const paginationPlugin = this.tbSelf.paginationPlugin;
    const paginationRef = paginationPlugin.paginationRef;
    if (paginationPlugin.isStopScrolling()) return;
    const wrapperHeight = this.verticalScroll.offsetHeight;
    const page = paginationRef.page;
    const pageSize = paginationRef.pageSize;
    const rowSize = this.tbSelf?.themeService?.rowSize;
    const min = rowSize * pageSize * page || 0;
    const max = rowSize * pageSize * (page + 1) - wrapperHeight;
    if (pos > max) pos = max;
    if (pos < min) pos = min;
    if (min <= pos && pos <= max) {
      this.scrollService?.scroll(pos, type, undefined, e[delta]);
      this.latestScrollUpdate(type);
    }
  }

  /**
   * On horizontal mousewheel event
   * @param type
   * @param delta
   * @param e
   */
  private onHorizontalMouseWheel(
    type: HbrTableNS.DimensionType,
    delta: "deltaX" | "deltaY",
    e: WheelEvent
  ) {
    // e.preventDefault(); // hijacks scroll from page
    const pos = this.horizontalScroll.scrollLeft + e[delta];
    this.scrollService?.scroll(pos, type, undefined, e[delta]);
    this.latestScrollUpdate(type);
  }
}
