import {
	Component,
	Element,
	Event,
	EventEmitter,
	Prop,
	VNode,
	h,
} from "@stencil/core";
//import { HTMLStencilElement } from '@stencil/core/internal';
import { debounce } from "../../utils/function-helper";

import { DATA_COL, DATA_ROW } from "../../table-sub/utils/consts";
import ColumnService, { ColumnSource, RowSource } from "./columnService";

import { HbrTableNS, Observable, Selection } from "../../table-sub/interfaces";
import GroupingRowRenderer from "../../table-sub/plugins/groupingRow/grouping.row.renderer";
import { isGrouping } from "../../table-sub/plugins/groupingRow/grouping.service";
import { getSourceItem } from "../../table-sub/store/dataSource/data.store";
import CellRenderer from "./cellRenderer";
import RowRenderer, { PADDING_DEPTH } from "./rowRenderer";

type TableContext = {
	paginationPlugin?: {
		getRows: (
			rows: HbrTableNS.VirtualPositionItem[],
		) => HbrTableNS.VirtualPositionItem[];
	};
	subRowTemplate?: (
		createElement: HbrTableNS.HyperFunc<VNode>,
		props: HbrTableNS.ColumnDataSchemaModel,
		table: unknown,
	) => VNode;
};

@Component({
	tag: "hbr-table-data",
	styleUrl: "data.scss",
})
export class HbrgrData {
	private columnService: ColumnService;
	private cellsDidRender = [];
	private cellsDisconnected = [];
	private debouncedHandleRender: () => void;
	@Element() element!: HTMLHbrTableDataElement;

	@Prop() readonly: boolean;
	@Prop() range: boolean;
	@Prop() canDrag: boolean;

	@Prop() rowClass: string;
	@Prop() rowSelectionStore: Observable<Selection.SelectionStoreState>;
	@Prop() viewportRow: Observable<HbrTableNS.ViewportState>;
	@Prop() viewportCol: Observable<HbrTableNS.ViewportState>;

	@Prop() dimensionRow: Observable<HbrTableNS.DimensionSettingsState>;

	/** Static stores, not expected to change during component lifetime */
	@Prop() colData: ColumnSource;
	@Prop() dataStore: RowSource;
	@Prop() tbSelf: TableContext;

	@Event() dragStartCell: EventEmitter<MouseEvent>;

	/**  After columns and rows rendered */
	@Event() internalAfterLoad: EventEmitter;

	connectedCallback() {
		this.columnService = new ColumnService(this.dataStore, this.colData);
		this.debouncedHandleRender = debounce(this.handleRender.bind(this), 1000);
	}
	disconnectedCallback() {
		this.cellsDisconnected.forEach((cell) => cell(this.tbSelf));
	}

	componentDidRender() {
		this.cellsDidRender.forEach((cell) => cell(this.tbSelf));
	}

	handleRender() {
		this.internalAfterLoad.emit();
	}

	render() {
		let rows = this.viewportRow.get("items");
		const cols = this.viewportCol.get("items");
		if (!this.columnService.columns.length || !rows.length || !cols.length) {
			return "";
		}
		const range = this.rowSelectionStore?.get("range");
		const rowsEls: VNode[] = [];

		const depth = this.dataStore.get("groupingDepth");
		if (this.tbSelf?.paginationPlugin?.getRows) {
			rows = this.tbSelf?.paginationPlugin?.getRows(rows);
		}
		for (const rgRow of rows) {
			const dataRow = getSourceItem(this.dataStore, rgRow.itemIndex);
			/** grouping */
			if (isGrouping(dataRow)) {
				rowsEls.push(
					<GroupingRowRenderer
						{...rgRow}
						model={dataRow}
						hasExpand={this.columnService.hasGrouping}
					/>,
				);
				continue;
			}
			/** grouping end */

			const cells: (VNode | string | undefined)[] = [];
			let rowClass = this.rowClass
				? this.columnService.getRowClass(rgRow.itemIndex, this.rowClass)
				: "";
			if (range && rgRow.itemIndex >= range.y && rgRow.itemIndex <= range.y1) {
				rowClass += " focused-rgRow";
			}

			let model: HbrTableNS.ColumnDataSchemaModel;
			cols.forEach((rgCol) => {
				model = this.columnService.rowDataModel(
					rgRow.itemIndex,
					rgCol.itemIndex,
				);
				cells.push(
					this.getCellRenderer(
						rgRow,
						rgCol,
						this.canDrag,
						/** grouping apply*/ this.columnService.hasGrouping ? depth : 0,
					),
				);
			});

			let customSubRow = null;
			const subRowTemplate = this.tbSelf.subRowTemplate;
			if (
				subRowTemplate &&
				!Object.prototype.hasOwnProperty.call(model.column ?? {}, "pin")
			) {
				// @ts-ignore
				customSubRow = subRowTemplate(
					h as unknown as HbrTableNS.HyperFunc<VNode>,
					getSourceItem(this.dataStore, rgRow.itemIndex),
					this.tbSelf,
				);
			}

			rowsEls.push(
				<RowRenderer
					rowClass={rowClass}
					size={rgRow.size}
					start={rgRow.start}
					model={model}
					customSubRow={customSubRow}
				>
					{cells}
				</RowRenderer>,
			);
		}

		// HACK - to emit an event after the rows actually appended to DOM
		this.debouncedHandleRender();

		return rowsEls;
	}

	private getCellRenderer(
		rgRow: HbrTableNS.VirtualPositionItem,
		rgCol: HbrTableNS.VirtualPositionItem,
		draggable = false,
		depth = 0,
	) {
		const model = this.columnService.rowDataModel(
			rgRow.itemIndex,
			rgCol.itemIndex,
		);
		const defaultProps: HbrTableNS.CellProps = {
			[DATA_COL]: rgCol.itemIndex,
			[DATA_ROW]: rgRow.itemIndex,
			style: {
				width: `${rgCol.size}px`,
				transform: `translateX(${rgCol.start}px)`,
			},
		};
		if (depth && !rgCol.itemIndex) {
			defaultProps.style.paddingLeft = `${PADDING_DEPTH * depth}px`;
		}
		const props = this.columnService.mergeProperties(
			rgRow.itemIndex,
			rgCol.itemIndex,
			defaultProps,
		);
		const custom = this.columnService.customRenderer(
			rgRow.itemIndex,
			rgCol.itemIndex,
			model,
			this.tbSelf,
		);

		// if custom render
		if (typeof custom !== "undefined") {
			const customDidRender = this.columnService.customDidRender(
				rgRow.itemIndex,
				rgCol.itemIndex,
				model,
				custom,
			);
			if (customDidRender) {
				!this.cellsDidRender.includes(customDidRender) &&
					this.cellsDidRender.push(customDidRender);
			}
			const customDisconnected = this.columnService.customDisconnected(
				rgRow.itemIndex,
				rgCol.itemIndex,
				model,
				custom,
			);
			if (customDisconnected) {
				!this.cellsDisconnected.includes(customDisconnected) &&
					this.cellsDisconnected.push(customDisconnected);
			}
			return (
				<div {...props} role="cell">
					{custom}
				</div>
			);
		}

		// something is wrong with data
		if (!model.column) {
			console.error("Investigate column problem");
			return;
		}

		// if regular render
		return (
			<div {...props} role="cell">
				<CellRenderer
					model={model}
					canDrag={draggable}
					onDragStart={(e) => this.dragStartCell.emit(e)}
				/>
			</div>
		);
	}
}
