import { HbrTableNS } from "../interfaces";
import { scaleValue } from "../utils/utils";

interface Config {
	beforeScroll(e: HbrTableNS.ViewPortScrollEvent): void;
	afterScroll(e: HbrTableNS.ViewPortScrollEvent): void;
}

type Params = {
	contentSize: number;
	virtualContentSize?: number;
	clientSize: number;
	virtualSize: number;
	maxSize?: number;
};

const initialParams: Params = {
	contentSize: 0,
	clientSize: 0,
	virtualSize: 0,
	maxSize: 0,
};

export default class LocalScrollService {
	private preventArtificialScroll: Record<
		HbrTableNS.DimensionType,
		number | null
	> = { rgRow: null, rgCol: null };
	// to check if scroll changed
	private previousScroll: Record<HbrTableNS.DimensionType, number> = {
		rgRow: 0,
		rgCol: 0,
	};
	private params: Record<HbrTableNS.DimensionType, Params> = {
		rgRow: { ...initialParams },
		rgCol: { ...initialParams },
	};

	constructor(private cfg: Config) {}

	static getVirtualContentSize(
		contentSize: number,
		clientSize: number,
		virtualSize = 0,
	): number {
		return contentSize + (virtualSize ? clientSize - virtualSize : 0);
	}

	setParams(params: Params, dimension: HbrTableNS.DimensionType) {
		const virtualContentSize = LocalScrollService.getVirtualContentSize(
			params.contentSize,
			params.clientSize,
			params.virtualSize,
		);
		this.params[dimension] = {
			...params,
			maxSize: virtualContentSize - params.clientSize,
			virtualContentSize,
		};
	}

	// apply scroll values after scroll done
	setScroll(e: HbrTableNS.ViewPortScrollEvent) {
		this.cancelScroll(e.dimension);
		this.preventArtificialScroll[e.dimension] = window.requestAnimationFrame(
			() => {
				const params = this.getParams(e.dimension);
				e.coordinate = Math.ceil(e.coordinate);
				this.previousScroll[e.dimension] = this.wrapCoordinate(
					e.coordinate,
					params,
				);
				this.preventArtificialScroll[e.dimension] = null;
				this.cfg.afterScroll({
					...e,
					coordinate: params.virtualSize
						? this.convert(e.coordinate, params, false)
						: e.coordinate,
				});
			},
		);
	}

	// initiate scrolling event
	scroll(
		coordinate: number,
		dimension: HbrTableNS.DimensionType,
		force = false,
		delta?: number,
		scroll?: HbrTableNS.ViewPortScrollEventScroll,
	) {
		this.cancelScroll(dimension);
		if (!force && this.previousScroll[dimension] === coordinate) {
			this.previousScroll[dimension] = 0;
			return;
		}

		const param: Params = this.getParams(dimension);
		this.cfg.beforeScroll({
			dimension: dimension,
			coordinate: param.virtualSize
				? this.convert(coordinate, param)
				: coordinate,
			delta,
			scroll
		});
	}

	private getParams(dimension: HbrTableNS.DimensionType): Params {
		return this.params[dimension];
	}

	// check if scroll outside of region to avoid looping
	private wrapCoordinate(c: number, param: Params): number {
		if (c < 0) {
			return 0;
		}

		if (c > param.maxSize) {
			return param.maxSize;
		}
		return c;
	}

	// prevent already started scroll, performance optimization
	private cancelScroll(dimension: HbrTableNS.DimensionType): boolean {
		if (typeof this.preventArtificialScroll[dimension] === "number") {
			window.cancelAnimationFrame(this.preventArtificialScroll[dimension]);
			this.preventArtificialScroll[dimension] = null;
			return true;
		}
		return false;
	}

	/* convert virtual to real and back, scale range */
	private convert(pos: number, param: Params, toReal = true): number {
		const minRange: number = param.clientSize;
		const from: [number, number] = [0, param.virtualContentSize - minRange];
		const to: [number, number] = [0, param.contentSize - param.virtualSize];
		if (toReal) {
			return scaleValue(pos, from, to);
		}
		return scaleValue(pos, to, from);
	}
}
