import { type VNode, h } from "@stencil/core";
import { dotsSix } from "../../../icons";
import type { HbrTableNS } from "../../table-sub/interfaces";
import { DRAGGABLE_CLASS, DRAG_ICON_CLASS } from "../../table-sub/utils/consts";
import getBootstrapConfig from "../../utils/getBootstrapConfig";
import ColumnService from "./columnService";

type Props = {
	model: HbrTableNS.ColumnDataSchemaModel;
	canDrag?: boolean;
	onDragStart?(e: MouseEvent): void;
};

const CellRenderer = ({ model, canDrag, onDragStart }: Props) => {
	const customSystemIcons = getBootstrapConfig()?.systemIcons;
	const els: (VNode | string)[] = [];
	if (model.column.rowDrag && isRowDragService(model.column.rowDrag, model)) {
		const { model: curModel } = model;
		// hide children drag button limited to parent rows only. version 2.9.18
		if (curModel?.childrenRow && curModel?.parentId) {
			return els;
		}
		if (canDrag) {
			els.push(
				<span class={DRAGGABLE_CLASS} onMouseDown={(e) => onDragStart(e)}>
					<span class={DRAG_ICON_CLASS} />
					<hbr-button
						size="xsmall"
						variant="text"
						class="hbr-css__table-row-drag-button"
					>
						<hbr-icon asset={customSystemIcons?.["dots-six"] || dotsSix} />
					</hbr-button>
				</span>,
			);
		} else {
			els.push(<span class={DRAGGABLE_CLASS} />);
		}
	}
	els.push(`${ColumnService.getData(model.model[model.prop])}`);
	return els;
};

export default CellRenderer;

function isRowDragService(
	rowDrag: HbrTableNS.RowDrag,
	model: HbrTableNS.ColumnDataSchemaModel,
): boolean {
	if (typeof rowDrag === "function") {
		return rowDrag(model);
	}
	return !!rowDrag;
}
