import { Fragment, VNode, h } from "@stencil/core";
import { HbrTableNS } from "../../table-sub/interfaces";
import { ResizableElement } from "../../table-sub//services/resizable.directive";
import ColumnService from "../table-data/columnService";
import { dispatch, type Target } from "../../table-sub/plugins/dispatcher"
import {COLUMN_CLICK} from "../../table-sub/plugins/moveColumn/columnDragPlugin"

type Props = {
	data?: HbrTableNS.ColumnRegular;
	props: HbrTableNS.CellProps;
	columnDidRender?: Array<any>;
	isHeaderSlot?: boolean;
	table: HTMLHbrTableElement;
};

export const HeaderCellRenderer = (
	{ data, props, isHeaderSlot, columnDidRender, table }: Props,
	children: VNode[]
): VNode => {
	const text: string = data?.name;
	const hiddenText: string = data?.hiddenText
	let colTemplate: VNode | VNode[] | string;
	let cellProps = props;
	if (data?.columnTemplate) {
		colTemplate = data.columnTemplate(h, data, table);
		const didRender = data?.columnDidRender;
		if (didRender) columnDidRender?.push([didRender, data, colTemplate]);
	}
	if (data?.columnProperties) {
		const extra = data.columnProperties(data);
		if (extra && typeof extra === "object") {
			cellProps = ColumnService.doMerge(props, extra);
		}
	}

	if (data?.columnFooterTemplate) {
		console.warn("hbr-table: do NOT use columnFooterTemplate API!");
		data.columnFooterTemplate(h, data, table);
	}

	return (
		<ResizableElement {...cellProps}
			onMouseDown={(e: MouseEvent) => {
				const target = e.currentTarget as Target
				dispatch(target, COLUMN_CLICK, {
					data,
					event: e,
				});
			}}
		>
			{isHeaderSlot ? (
				<hbr-table-header-cell data={data}>
					{colTemplate}
					<div slot="top-end">{children}</div>
				</hbr-table-header-cell>
			) : (
				<Fragment>
					<div class="header-content" role="columnheader">{colTemplate || text}
						{hiddenText && <hbr-visually-hidden>{hiddenText}</hbr-visually-hidden>}
					</div>
					{children}
				</Fragment>
			)}
		</ResizableElement>
	);
};
