import { Component, Host, Prop, h } from "@stencil/core";
import { throttle } from "../../utils/function-helper";
import { HbrTableNS, Observable, Selection } from "../../table-sub/interfaces";
import { TMP_SELECTION_BG_CLASS } from "../../table-sub/utils/consts";
import { getElStyle } from "../table-overlay/selection.utils";

@Component({
  tag: "hbr-temp-range",
  styleUrl: "temp-range-style.scss",
})
export class HbrgrFocus {
  el: HTMLElement;

  /** Dynamic stores */
  @Prop() selectionStore: Observable<Selection.SelectionStoreState>;
  @Prop() dimensionRow: Observable<HbrTableNS.DimensionSettingsState>;
  @Prop() dimensionCol: Observable<HbrTableNS.DimensionSettingsState>;
  private readonly onChange = throttle(
    (e: HTMLElement) => this.doChange(e),
    300
  );

  private doChange(e: HTMLElement): void {
    e?.scrollIntoView({
      block: "nearest",
      inline: "nearest",
    });
  }

  componentDidRender(): void {
    if (this.el) {
      this.onChange(this.el);
    }
  }

  render() {
    const data = this.selectionStore.get("tempRange");
    const type = this.selectionStore.get("tempRangeType");
    if (!data) {
      return;
    }
    let directionY = "bottom";
    let directionX = "right";
    const range = this.getRange();
    if (!range) {
      return;
    }
    if (data.y < range.y) {
      directionY = "top";
    }
    if (data.x < range.x) {
      directionX = "left";
    }
    const directionClass = `${directionX} ${directionY}`;
    const style = getElStyle(
      data,
      this.dimensionRow.state,
      this.dimensionCol.state
    );
    return (
      <Host
        class={{
          [TMP_SELECTION_BG_CLASS]: true,
          [type || ""]: true,
        }}
        style={style}
      >
        <div
          class={directionClass}
          ref={(e: HTMLElement) => {
            this.el = e;
          }}
        />
      </Host>
    );
  }

  private getRange(): Selection.RangeArea | null {
    const range = this.selectionStore.get("range");
    if (range) {
      return range;
    }
    const focus = this.selectionStore.get("focus");
    if (!focus) {
      return null;
    }
    return {
      ...focus,
      x1: focus.x,
      y1: focus.y,
    };
  }
}
