import { VNode, h } from "@stencil/core";
import { HbrTableNS, Selection } from "../../table-sub/interfaces";
import { FilterButton } from "../../table-sub//plugins/filter/filter.button";
import { SortingSign } from "../../table-sub//plugins/sorting/sorting.sign";
import { ResizeEvent } from "../../table-sub//services/resizable.directive";
import {
	DATA_COL,
	FOCUS_CLASS,
	HEADER_CLASS,
	HEADER_SORTABLE_CLASS,
	MIN_COL_SIZE,
} from "../../table-sub//utils/consts";
import { HeaderCellRenderer } from "./headerCellRenderer";

type Props = {
	column: HbrTableNS.VirtualPositionItem;
	data?: HbrTableNS.ColumnRegular;
	range?: Selection.RangeArea;
	canResize?: boolean;
	canFilter?: boolean;
	onResize?(e: ResizeEvent): void;
	onClick?(data: HbrTableNS.InitialHeaderClick): void;
	columnDidRender?: Array<any>;
	onDoubleClick?(data: HbrTableNS.InitialHeaderClick): void;
	table: any;
};

const HeaderRenderer = (p: Props): VNode => {
  const isHeaderSlot = !!p?.table?.headerSlot && p.data?.headerSlot !== false;
	const cellClass: { [key: string]: boolean } = {
		[HEADER_CLASS]: true,
		[HEADER_SORTABLE_CLASS]: !!p.data?.sortable,
		"hbr-table-header-content-sort": isHeaderSlot,
		"hbr-table-header-align-right": p.data?.headerAlign === "right" && !isHeaderSlot,
    "hbr-table-header-slot-align-right": p.data?.headerAlign === "right" && isHeaderSlot,
		"hbr-table-header-align-center": p.data?.headerAlign === "center" && !isHeaderSlot,
    "hbr-table-header-slot-align-center": p.data?.headerAlign === "center" && isHeaderSlot
	};
	if (p.data?.order) {
		cellClass[p.data.order] = true;
	}
	const dataProps = {
		[DATA_COL]: p.column.itemIndex,
		canResize: p.canResize,
		minWidth: p.data?.minSize || MIN_COL_SIZE,
		maxWidth: p.data?.maxSize,
		active: ["r"],
		class: cellClass,
		style: {
			width: `${p.column.size}px`,
			transform: `translateX(${p.column.start}px)`,
		},
		ariaSort: p.data?.order === "asc" ? "ascending" : p.data?.order === "desc" ? "descending" : undefined,
		onResize: p.onResize,
		onDoubleClick(originalEvent: MouseEvent) {
			p.onDoubleClick({
				column: p.data,
				index: p.column.itemIndex,
				originalEvent,
			});
		},
		onClick(originalEvent: MouseEvent) {
			if (originalEvent.defaultPrevented || !p.onClick) {
				return;
			}
      if (isHeaderSlot) {
        const targetEle = originalEvent.target as HTMLElement;
        if (targetEle.hasAttribute("data-header-sort")) {
          p.onClick({column: p.data, index: p.column.itemIndex, originalEvent});
        }
      } else {
        p.onClick({column: p.data, index: p.column.itemIndex, originalEvent});
      }
		},
	};
	if (p?.data?.hasOwnProperty("canResize")) {
		dataProps.canResize = p.data?.canResize;
	}
	if (p.range) {
		if (p.column.itemIndex >= p.range.x && p.column.itemIndex <= p.range.x1) {
			if (typeof dataProps.class === "object") {
				dataProps.class[FOCUS_CLASS] = true;
			}
		}
	}

	return (
		<HeaderCellRenderer
			data={p.data}
      isHeaderSlot={isHeaderSlot}
			props={dataProps}
			columnDidRender={p.columnDidRender}
			table={p.table}
		>
			{p.data?.sortable ? <SortingSign column={p.data} table={p.table} /> : ""}
			{p.canFilter && p.data?.filter !== false ? (
				<FilterButton column={p.data} />
			) : (
				""
			)}
		</HeaderCellRenderer>
	);
};

export default HeaderRenderer;
