type Props = {
	column: HbrTableNS.ColumnRegular;
	table: HTMLHbrTableElement;
};
export const SortingSign = ({ column, table }: Props) => {
	return table.theme === "magnetic" ? (
		<span
			data-header-sort="true"
			class={`hbr-table-header-sorting-wrapper ${
				column.order === undefined ? "default" : column.order
			}`}
		>
			{column.order === undefined ? (
				<Default class="hbr-table-header-sorting-default" />
			) : (
				""
			)}
			{column.order === "asc" ? <Asc /> : ""}
			{column.order === "desc" ? <Desc /> : ""}
		</span>
	) : (
		<i class={column.order} />
	);
};
