import { VNode, h } from "@stencil/core";
import { JSXBase } from "@stencil/core/internal";
import { INTERNAL_CHILD_CELL_CLASS } from "../../../src/table-sub/utils/consts";

export interface RowProps extends JSXBase.HTMLAttributes {
	size: number;
	start: number;
	rowClass?: string;
	depth?: number;
	model?: any;
	customSubRow?: any;
}

export const PADDING_DEPTH = 10;

const RowRenderer = (
	{ rowClass, size, start, style, depth, model, customSubRow }: RowProps,
	cells: VNode[],
) => {
	let attr = {};
	if (model?.model?.id) {
		attr = {
			"data-row-id": model.model.id,
		};
	}
	return (
		<div
			class={`rgRow ${rowClass || ""}`}
			role="row"
			{...attr}
			style={{
				...style,
				height: `${size}px`,
				transform: `translateY(${start}px)`,
				paddingLeft: depth ? `${PADDING_DEPTH * depth}px` : undefined,
			}}
		>
			{cells}
			{customSubRow
				? <div class={INTERNAL_CHILD_CELL_CLASS}>
					{customSubRow}
				</div>
				: null
			}
		</div>
	);
};

export default RowRenderer;
