import { h } from "@stencil/core";
import { HbrTableNS, Observable, Selection } from "../../table-sub/interfaces";
import { DataSourceState } from "../../table-sub/store/dataSource/data.store";
import { getRange } from "../../table-sub/store/selection/selection.helpers";
import SelectionStoreService from "../../table-sub/store/selection/selection.store.service";
import ColumnService from "../table-data/columnService";

type Config = {
  selectionStoreService: SelectionStoreService;
  columnService: ColumnService;
  dataStore: Observable<
    DataSourceState<HbrTableNS.DataType, HbrTableNS.DimensionRows>
  >;
  onRangeApply(data: HbrTableNS.DataLookup, range: Selection.RangeArea): void;
  internalCopy(): Event;
};

export class ClipboardService {
  private clipboard: HTMLHbrClipboardElement;
  constructor(private sv: Config) {}
  private onCopy(e: DataTransfer) {
    const canCopy = this.sv.internalCopy();
    if (canCopy.defaultPrevented) {
      return false;
    }
    const focus = this.sv.selectionStoreService.focused;
    let range = this.sv.selectionStoreService.ranged;
    let data: HbrTableNS.DataFormat[][];
    if (!range) {
      range = getRange(focus, focus);
    }
    if (range) {
      const columns = [...this.sv.columnService.columns];
      const props = columns.slice(range.x, range.x1 + 1).map((v) => v.prop);
      data = this.sv.columnService.copyRangeArray(
        range,
        props,
        this.sv.dataStore
      );
    }
    this.clipboard.doCopy(e, data);
    return true;
  }

  renderClipboard() {
    return (
      <hbr-clipboard
        onCopyRegion={(e) => this.onCopy(e.detail)}
        ref={(e) => {
          this.clipboard = e;
        }}
        onPasteRegion={(e) => this.onPaste(e.detail)}
      />
    );
  }

  private onPaste(data: string[][]) {
    const focus = this.sv.selectionStoreService.focused;
    const isEditing = this.sv.selectionStoreService.edited !== null;
    if (!focus || isEditing) {
      return;
    }
    const { changed, range } = this.sv.columnService.getTransformedDataToApply(
      focus,
      data
    );
    this.sv.onRangeApply(changed, range);
  }
}
